import algoliasearch from 'algoliasearch';

// Admin client for indexing (server-side only)
const client = algoliasearch(
  process.env.ALGOLIA_APP_ID!,
  process.env.ALGOLIA_ADMIN_API_KEY!
);
const index = client.initIndex('products');

// Index some records
await index.saveObjects([
  { objectID: '1', name: 'iPhone 15 Pro', brand: 'Apple', price: 999 },
  { objectID: '2', name: 'Galaxy S24', brand: 'Samsung', price: 899 },
]);

// Search
const { hits } = await index.search('iphone', {
  hitsPerPage: 10,
  filters: 'price < 1000',
});

console.log('Results:', hits.map(h => h.name));

import { liteClient } from 'algoliasearch/lite';
import { InstantSearch, SearchBox, Hits } from 'react-instantsearch';

const searchClient = liteClient(
  process.env.NEXT_PUBLIC_ALGOLIA_APP_ID!,
  process.env.NEXT_PUBLIC_ALGOLIA_SEARCH_KEY! // Search-only key
);

function ProductHit({ hit }: { hit: Record<string, unknown> }) {
  return <div>{String(hit.name)} — ${String(hit.price)}</div>;
}

export function ProductSearch() {
  return (
    <InstantSearch searchClient={searchClient} indexName="products">
      <SearchBox placeholder="Search products..." />
      <Hits hitComponent={ProductHit} />
    </InstantSearch>
  );
}
